-- Pipeline de perguntas com Gemini, versão 2 (docs/jogo.md 7.1, "Banco de perguntas").
-- A IA só propõe a partir de uma página que o código baixou; o código aceita a pergunta apenas se o
-- trecho citado está na página e traz a resposta; um segundo modelo audita sem saber qual é a certa.
-- Nada daqui vai ao jogo sozinho: o que chega a pre_aprovada é exportado para dados/perguntas/ e
-- revisado por amostra antes do importar-perguntas. A tabela antiga staging_gt.perguntas fica como está.

create table if not exists staging_gt.rascunhos_perguntas (
  id bigint generated always as identity primary key,
  clube text not null,
  degrau text not null,
  tema text not null,
  pergunta text not null,
  certa text not null,
  errada1 text not null,
  errada2 text not null,
  errada3 text not null,
  fonte text not null,
  trecho text not null,
  modelo text not null,
  -- rascunho (passou nas travas do gerador) -> pre_aprovada (passou na auditoria) | reprovada
  status text not null default 'rascunho' check (status in ('rascunho', 'pre_aprovada', 'reprovada', 'exportada')),
  motivo text,
  auditoria_trecho text,
  auditoria_modelo text,
  criada_em timestamptz not null default now(),
  auditada_em timestamptz
);
create unique index if not exists rascunhos_perguntas_texto
  on staging_gt.rascunhos_perguntas (lower(regexp_replace(pergunta, '[^[:alnum:]]+', '', 'g')));
create index if not exists rascunhos_perguntas_status on staging_gt.rascunhos_perguntas (status, criada_em);

-- Propostas recusadas pelas travas do gerador: ficam registradas para ajustar o prompt.
create table if not exists staging_gt.recusas_perguntas (
  id bigint generated always as identity primary key,
  clube text not null,
  fonte text not null,
  proposta jsonb not null,
  motivo text not null,
  modelo text not null,
  criada_em timestamptz not null default now()
);

-- Páginas de onde o gerador tira as perguntas: fontes já revisadas dos CSVs (domínio aceito).
create table if not exists staging_gt.fontes_semente (
  url text not null,
  clube text not null,
  usos integer not null default 0,
  falhas integer not null default 0,
  ativa boolean not null default true,
  ultimo_uso timestamptz,
  primary key (url, clube)
);

on conflict do nothing;

alter table staging_gt.rascunhos_perguntas enable row level security;
alter table staging_gt.recusas_perguntas enable row level security;
alter table staging_gt.fontes_semente enable row level security;
revoke all on staging_gt.rascunhos_perguntas, staging_gt.recusas_perguntas, staging_gt.fontes_semente from anon, authenticated;
grant select, insert, update, delete on staging_gt.rascunhos_perguntas, staging_gt.recusas_perguntas, staging_gt.fontes_semente to service_role;

-- Crons: um lote pequeno por dia (horário de Brasília: gera às 6h, audita às 7h).
-- O corrigir-fontes continua pausado (era da tabela antiga).
do $$
declare
  v_job bigint;
begin
  select jobid into v_job from cron.job where jobname = 'job_gerar_conteudo';
  if v_job is not null then
    perform cron.alter_job(v_job, schedule := '0 9 * * *', active := true);
  end if;
  select jobid into v_job from cron.job where jobname = 'job_auditar_conteudo';
  if v_job is not null then
    perform cron.alter_job(v_job, schedule := '0 10 * * *', active := true);
  end if;
end;
$$;
